// Lanzar un proyectil con ángulo y velocidad inicial
public float velocidadInicial = 20f;
public float anguloGrados = 45f;

void Disparar()
{
    float angRad = anguloGrados * Mathf.Deg2Rad;  // convertir a radianes
    float vx = velocidadInicial * Mathf.Cos(angRad); // componente horizontal
    float vy = velocidadInicial * Mathf.Sin(angRad); // componente vertical

    Rigidbody rb = proyectil.GetComponent<Rigidbody>();
    rb.velocity = new Vector3(0, vy, vx); // en el plano Z (hacia adelante) y Y (arriba)
}

// Alternativamente con AddForce e Impulse
rb.AddForce(new Vector3(0, vy, vx), ForceMode.VelocityChange);

public class BalaDeCañon : MonoBehaviour
{
    public float velocidad = 25f;
    public float angulo = 45f;
    Rigidbody rb;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
        float rad = angulo * Mathf.Deg2Rad;
        // Aplicar velocidad inicial: la gravedad hará el resto
        rb.velocity = new Vector3(0f, velocidad * Mathf.Sin(rad), velocidad * Mathf.Cos(rad));
    }

    void OnCollisionEnter(Collision col)
    {
        // Explotar al impactar
        Instantiate(explosion, transform.position, Quaternion.identity);
        Destroy(gameObject);
    }
}

